/// <summary>
/// GUPPricingAttribute of table <c>InventTableModule</c> field TaxItemGroupId.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Product, GUPPricingAttributeSourceLevel::Line)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(InventTableModule, TaxItemGroupId), tableStr(TaxItemGroupHeading), fieldStr(TaxItemGroupHeading, TaxItemGroup))]
internal class GUPPricingAttributeInventTableModuleInventTaxItemGroupId extends GUPPricingAttributeInventTableModuleInvent implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return strFmt("%1 - %2", enum2Str(ModuleInventPurchSales::Invent), fieldPName(InventTableModule, TaxItemGroupId));
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);

    InventTableModule   inventTableModule;

    while select TaxItemGroupId from inventTableModule
        group by TaxItemGroupId
        where InventTablemodule.ModuleType == ModuleInventPurchSales::Invent
    {
        ret.add(inventTableModule.TaxItemGroupId);
    }
    return ret;
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    InventTableModule   inventTableModule;
    TaxItemGroupHeading taxItemGroupHeading;

    while select TaxItemGroupId from inventTableModule
        join taxItemGroupHeading
        group by TaxItemGroup, Name
        where inventTableModule.TaxItemGroupId == taxItemGroupHeading.TaxItemGroup
            && InventTablemodule.ModuleType == ModuleInventPurchSales::Invent
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(taxItemGroupHeading.TaxItemGroup, taxItemGroupHeading.Name);
        ret.add(valueObject);
    }
    return ret;
}
